SELECT 
  FROM ai_inference_cache
 WHERE row_hash = #{rowHash} AND prompt_version = #{promptVersion} AND tenant_id = #{tenantId}

mapper.insert:
MERGE INTO ai_inference_cache t USING (
SELECT #{e.rowHash,jdbcType=VARCHAR} AS rh, #{e.resultJson,jdbcType=VARCHAR} AS rj FROM DUAL
) s ON (t.row_hash = s.rh AND t.prompt_version = #{promptVersion}) WHEN NOT MATCHED THEN INSERT (row_hash, prompt_version, result_json, created_at) VALUES (s.rh, #{promptVersion}, s.rj, )
